let content = $input.first().json.content.parts[0].text;

try { // 1. 🔹 ล้าง format code block ออก (กรณีที่มีjson ...)
  content = content.replace(/^```json\n|^```\n|```$/g, '').trim();

  // 2. 🔹 แปลงเป็น JSON object
  const data = JSON.parse(content);

  // 3. 🔹 กำหนดโครงสร้างข้อมูล (Schema)
  const dataSchema = {
    type:        { required: true },
    class:       { required: true },
    timestamp:   { required: true },
    transac_id:  { required: true },
    amount:      { required: true, defaultOnNull: 0, type: 'float' },
    fee:         { required: true, defaultOnNull: 0, type: 'float' },
    note:         { required: true, defaultOnNull: null, type: 'string' },
  };

  // 4. 🔹 ดึง field ทั้งหมดจาก schema
  const allSchemaFields = Object.keys(dataSchema);

  // 5. 🔹 ดึง field ที่ required
  const requiredFields = allSchemaFields.filter(key => dataSchema[key].required);

  // 6. 🔹 ตรวจสอบว่าข้อมูลขาด field สำคัญไหม
  const missing = requiredFields.filter(f => !(f in data));
  if (missing.length > 0) {
    throw new Error(`Missing required fields: ${missing.join(', ')}`);
  }

  // 7. 🔹 สร้าง payload ที่จะส่งออก
  const successPayload = {
    status: "success"
  };

  // 8. 🔹 วนลูป schema เพื่อแปลงและเติมค่า
  allSchemaFields.forEach(key => {
    const value = data[key];
    const schemaDef = dataSchema[key];

    // ✅ 1. ถ้าเป็น null และมี default ให้ใช้ default
    if (value === null && 'defaultOnNull' in schemaDef) {
      successPayload[key] = schemaDef.defaultOnNull;
    } 
    // ✅ 2. ถ้า type เป็น float → ล้างค่าและแปลงเป็น float
    else if (key in data && schemaDef.type === 'float') {
      // ล้างค่าที่ไม่ใช่ตัวเลข เช่น ฿ หรือ ,
      const cleaned = String(value).replace(/[^\d.-]/g, '');
      const floatValue = parseFloat(cleaned);

      successPayload[key] = isNaN(floatValue)
        ? (schemaDef.defaultOnNull || 0)
        : floatValue;
    } 
    // ✅ 3. ถ้ามีค่าอยู่แล้ว (ไม่ต้องแปลง)
    else if (key in data) {
      successPayload[key] = value;
    }
  });

  // 9. 🔹 เติม timestamp อัตโนมัติ ถ้าไม่มีใน input หรือค่าว่าง/null
  if (!successPayload.timestamp || successPayload.timestamp === null || successPayload.timestamp === "") {
    // ใช้รูปแบบ YYYY-MM-DD HH:mm:ss
    const now = new Date();
    const pad = n => n.toString().padStart(2, '0');
    const formatted = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())} ${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;
    successPayload.timestamp = formatted;
  }

  // ✅ 10. คืนผลลัพธ์สำเร็จ
  return [successPayload];

} catch (error) {
  // ❌ ถ้ามี error
  return [{
    status: "error",
    message: error.message || "Invalid input JSON format"
  }];
}

