let content = $input.first().json.content.parts[0].text;

try {
  // 1. 🔹 ล้าง format code block ออก (```json ... ```)
  content = content.replace(/^```json\n|^```\n|```$/g, '').trim();

  // 2. 🔹 แปลงเป็น JSON
  const data = JSON.parse(content);

  // 3. 🔹 กำหนด schema
  const dataSchema = {
    type:        { required: true },
    class:       { required: true },
    timestamp:   { required: true },
    transac_id:  { required: true },
    amount:      { required: true, defaultOnNull: 0, type: 'float' },
    fee:         { required: true, defaultOnNull: 0, type: 'float' },
  };

  // ฟังก์ชันแปลงและตรวจสอบแต่ละรายการ
  const processItem = (item) => {
    const allSchemaFields = Object.keys(dataSchema);
    const requiredFields = allSchemaFields.filter(k => dataSchema[k].required);
    const missing = requiredFields.filter(f => !(f in item));
    if (missing.length > 0) {
      throw new Error(`Missing required fields: ${missing.join(', ')}`);
    }

    const payload = {};

    allSchemaFields.forEach(key => {
      const value = item[key];
      const schemaDef = dataSchema[key];

      if (value === null && 'defaultOnNull' in schemaDef) {
        payload[key] = schemaDef.defaultOnNull;
      } 
      else if (schemaDef.type === 'float') {
        const cleaned = String(value).replace(/[^\d.-]/g, '');
        const floatValue = parseFloat(cleaned);
        payload[key] = isNaN(floatValue)
          ? (schemaDef.defaultOnNull || 0)
          : floatValue;
      } 
      else {
        payload[key] = value;
      }
    });

    // เติม timestamp ถ้าไม่มี
    if (!payload.timestamp || payload.timestamp === null || payload.timestamp === "") {
      const now = new Date();
      const pad = n => n.toString().padStart(2, '0');
      payload.timestamp = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())} ${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;
    }

    payload.status = "success";
    return payload;
  };

  // 4. 🔹 รองรับทั้ง array และ object เดี่ยว
  let outputItems = [];
  if (Array.isArray(data)) {
    outputItems = data.map(d => ({ json: processItem(d) }));
  } else {
    outputItems = [{ json: processItem(data) }];
  }

  // ✅ คืนค่าเป็นหลาย item
  return outputItems;

} catch (error) {
  // ❌ error
  return [{
    json: {
      status: "error",
      message: error.message || "Invalid input JSON format"
    }
  }];
}

