parameters.jsCode:
// Get all input items
const items = $input.all();
const outputItems = [];

// --- 1. ดึงค่า timestamp จาก 'Merge1' ---
// เราจะดึงค่านี้มาก่อนนอก Loop เพราะมันเป็นค่าเดียวกันสำหรับทุกไฟล์
const merge1Data = $('Merge1').first();
if (!merge1Data || !merge1Data.json || !merge1Data.json.timestamp) {
  throw new Error("ไม่พบ .json.timestamp จาก Node 'Merge1'. กรุณาตรวจสอบว่า 'Merge1' ทำงานและมีข้อมูลครับ");
}

// นี่คือค่า timestamp ที่คุณต้องการ (เช่น '2024-01-01T16:47:01.847Z')
const timestampFromMerge1 = merge1Data.json.timestamp;

// --- 2. (แนะนำ) จัดรูปแบบ timestamp ให้เหมาะกับการเป็นชื่อไฟล์ ---
// เราไม่ควรใช้ '2024-01-01T16:47:01.847Z' ตรงๆ เพราะมีอักขระพิเศษ (:, .)
// เราควรแปลงมันเป็น Date object ก่อน แล้วค่อยจัดรูปแบบ
const dateObj = new Date(timestampFromMerge1);

const year = dateObj.getFullYear();
const month = String(dateObj.getMonth() + 1).padStart(2, '0');
const day = String(dateObj.getDate()).padStart(2, '0');
const hours = String(dateObj.getHours()).padStart(2, '0');
const minutes = String(dateObj.getMinutes()).padStart(2, '0');
const seconds = String(dateObj.getSeconds()).padStart(2, '0');

// นี่คือชื่อไฟล์ที่ปลอดภัย (เช่น '2024-01-01_16-47-01')
const formattedFileName = `${year}-${month}-${day}_${hours}-${minutes}-${seconds}`;


// --- 3. Loop ประมวลผลไฟล์ ---
for (let i = 0; i < items.length; i++) {
  const item = items[i];

  // --- !! สำคัญมาก !! ---
  // จากรูปหน้าจอของคุณ (image_98a982.png)
  // key ของไฟล์คุณคือ 'imgFile' ไม่ใช่ 'data'
  const binaryInputKey = 'imgFile'; // <--- แก้ไขตรงนี้

  // 4. ตรวจสอบว่ามีไฟล์แนบมาจริง
  if (!(item.binary && item.binary[binaryInputKey])) {
    console.warn(`Item index ${i} ไม่มี binary property '${binaryInputKey}'. กำลังข้าม...`);
    continue; // ข้ามไป item ถัดไป
  }

  // 5. ดึงนามสกุลไฟล์เดิม
  const binaryData = item.binary[binaryInputKey];
  let fileExtension = binaryData.fileExtension;

  // พยายามเดานามสกุลจาก MimeType ถ้าไม่มี
  if (!fileExtension && binaryData.mimeType) {
    if (binaryData.mimeType === 'image/jpeg') fileExtension = 'jpg';
    else if (binaryData.mimeType === 'image/png') fileExtension = 'png';
  }

  // 6. ตั้งชื่อไฟล์ใหม่
  let desiredFileName = formattedFileName;
  if (fileExtension) {
    desiredFileName = `${formattedFileName}.${fileExtension}`;
  }

  console.log(`กำลังตั้งชื่อไฟล์: ${desiredFileName}`);

  // 7. แก้ไข property ของ binary object
  binaryData.fileName = desiredFileName;

  // 8. ส่ง item ที่แก้ไขแล้วออกไป
  outputItems.push(item);
}

// Return array ที่มี items ที่ถูกแก้ไขแล้ว
return outputItems;

