parameters.jsCode:
// 1. ดึงค่า Timestamp จาก Item ตัวแรก
const timestamp = $input.first().json.timestamp;

// 2. แปลงเวลาเป็น GMT+7 และจัด Format (ใช้ Library Luxon ที่มีใน n8n)
const formattedDate = DateTime.fromMillis(timestamp)
                        .setZone('Asia/Bangkok')
                        .toFormat('yyyy-MM-dd HH:mm');

// 3. Loop ใส่ค่านี้ลงไปในทุก Item (หรือทำ Logic อื่นตามต้องการ)
for (const item of $input.all()) {
  item.json.timestamp_formatted = formattedDate; // Field ใหม่ที่แปลงแล้ว
}

return $input.all();

// ดึงข้อมูลจาก Node ก่อนหน้า
const items = $input.all();

// วนลูปเช็คทุก item (ปกติจะมีแค่ 1 item ถ้าเป็น aggregate result)
return items.map(item => {
  const data = item.json;

  // เช็คว่ามี field 'income' หรือไม่ (ถ้า query เจอต้องมี, ถ้าไม่เจอจะไม่มี)
  if (data.income === undefined) {
    // กรณี: ไม่พบข้อมูล (No Data Found) -> ให้สร้างค่า 0 ปลอมขึ้นมา
    return {
      json: {
        ...data, // เก็บข้อมูลเดิมไว้ (พวก userId, timestamp)
        income: 0,
        expense: 0,
        balance: 0,
        class_breakdown: {
          Food: 0,
          Beverage: 0,
          Transfer: 0,
          Bill: 0,
          Shopping: 0,
          Fare: 0,
          Subscription: 0,
          Other: 0
        }
      }
    };
  }

  // กรณี: พบข้อมูลปกติ -> ส่งผ่านไปเลย
  return item;
});

