// 1. 🔹 ดึงข้อความจากโครงสร้าง Agent Output (ตามที่คุณส่งมา)
// path คือ output[0] -> content[0] -> text
const agentOutput = $input.first().json.output;
let content = "";

if (agentOutput && agentOutput[0] && agentOutput[0].content && agentOutput[0].content[0]) {
    content = agentOutput[0].content[0].text;
} else {
    // กันเหนียว กรณีโครงสร้างเปลี่ยน
    content = "[]"; 
}

try {
  // 2. 🔹 ล้าง Markdown Code Block (```json ... ```)
  content = content.replace(/^```json\s*|^```\s*|```$/g, '').trim();

  // 3. 🔹 แปลงเป็น JSON Object
  let data = JSON.parse(content);

  // 4. 🔹 ถ้า AI เผลอส่งมาเป็น Object เดียว (ลืมใส่ []) ให้เราช่วยใส่ให้
  if (!Array.isArray(data)) {
    data = [data];
  }

  // 5. 🔹 Schema & Data Processing (Logic เดิมของคุณ)
  const dataSchema = {
    type:        { required: true },
    class:       { required: true },
    timestamp:   { required: true },
    transac_id:  { required: true },
    amount:      { required: true, defaultOnNull: 0, type: 'float' },
    fee:         { required: true, defaultOnNull: 0, type: 'float' },
  };

  const processItem = (item) => {
    const payload = {};
    const allSchemaFields = Object.keys(dataSchema);

    allSchemaFields.forEach(key => {
      let value = item[key];
      const schemaDef = dataSchema[key];

      // จัดการค่า Null/Default
      if ((value === null || value === undefined) && 'defaultOnNull' in schemaDef) {
        value = schemaDef.defaultOnNull;
      }

      // จัดการตัวเลข
      if (schemaDef.type === 'float') {
        const cleaned = String(value).replace(/[^\d.-]/g, '');
        const floatValue = parseFloat(cleaned);
        payload[key] = isNaN(floatValue) ? (schemaDef.defaultOnNull || 0) : floatValue;
      } else {
        payload[key] = value;
      }
    });

    // จัดการ Timestamp (ถ้าไม่มี/ค่าว่าง ให้ใช้วันนี้)
    if (!payload.timestamp) {
      const now = new Date();
      const pad = n => n.toString().padStart(2, '0');
      payload.timestamp = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())} ${pad(now.getHours())}:${pad(now.getMinutes())}`;
    }

    payload.status = "success";
    return payload;
  };

  // 6. 🔹 Return output แยก Item (เพื่อให้ n8n ทำงานต่อทีละรายการ)
  return data.map(item => ({
    json: processItem(item)
  }));

} catch (error) {
  // กรณี Error ให้ส่งกลับไปบอก
  return [{
    json: {
      status: "error",
      message: error.message || "Invalid JSON format",
      raw_content: content
    }
  }];
}

